-- Synthetic fixtures only, guaranteed rollback. Run after diriqent-fixes.sql on authorized test project.
do $test$
declare
 ua uuid:=gen_random_uuid(); uw uuid:=gen_random_uuid(); uf uuid:=gen_random_uuid();
 pa uuid:=gen_random_uuid(); pw uuid:=gen_random_uuid(); pf uuid:=gen_random_uuid();
 c uuid:=gen_random_uuid(); foreign_c uuid:=gen_random_uuid(); customer uuid:=gen_random_uuid(); foreign_customer uuid:=gen_random_uuid();
 op uuid:=gen_random_uuid(); op_cancel uuid:=gen_random_uuid(); op_failed uuid:=gen_random_uuid(); op_demotion uuid:=gen_random_uuid(); op_worker uuid:=gen_random_uuid(); op_proposal uuid:=gen_random_uuid(); op_ocr uuid:=gen_random_uuid();
 credit uuid; attempt uuid; body jsonb; payload jsonb; proposal jsonb; job uuid; answer jsonb:='{"answer":"Ověřený testovací výsledek","jobProposal":null}';
 marker text:='AI'||right(replace(gen_random_uuid()::text,'-',''),16); fp text:=repeat('a',64); failure text; passed integer:=0;
begin
 begin
  insert into auth.users(id,email,raw_user_meta_data) values(ua,marker||'admin@example.invalid','{}'),(uw,marker||'worker@example.invalid','{}'),(uf,marker||'foreign@example.invalid','{}');
  insert into public.profiles(id,auth_user_id,user_id,full_name) values(pa,ua,ua,'AI test admin'),(pw,uw,uw,'AI test worker'),(pf,uf,uf,'AI foreign admin');
  insert into public.companies(id,name) values(c,'AI synthetic test'),(foreign_c,'AI foreign synthetic');
  insert into public.company_members(company_id,profile_id,role,is_active) values(c,pa,'company_admin',true),(c,pw,'worker',true),(foreign_c,pf,'company_admin',true);
  insert into public.customers(id,company_id,name) values(customer,c,'Allowed customer'),(foreign_customer,foreign_c,'FORBIDDEN CUSTOMER');
  insert into private.company_module_rollouts(company_id,product,livemode) select co,pr,false from unnest(array[c,foreign_c]) companies(co) cross join unnest(array['diriqo_core','ai_assistant','smart_quotes']) products(pr);
  insert into private.company_test_module_grants(company_id,product,source_ref,reason,valid_from,valid_until,history_until,capabilities)
   select co,pr,marker,'Synthetic AI rollback check',now()-interval '1 day',now()+interval '1 day',now()+interval '1 day',case pr
    when 'diriqo_core' then array['core.jobs.create','core.history.read','core.history.export']
    when 'ai_assistant' then array['ai_assistant.conversation.run','ai_assistant.history.read','ai_assistant.history.export']
    else array['smart_quotes.template.manage','smart_quotes.ocr.request','smart_quotes.history.read','smart_quotes.history.export'] end
   from unnest(array[c,foreign_c]) companies(co) cross join unnest(array['diriqo_core','ai_assistant','smart_quotes']) products(pr);
  perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';
  credit:=public.diriqent_test_credit_grant(c,10000,marker,'Synthetic AI credit only',now()+interval '1 day');
  assert public.diriqent_test_credit_grant(c,10000,marker,'Synthetic AI credit only',now()+interval '1 day')=credit,'credit source idempotence';passed:=passed+1;
  execute 'reset role';
  perform set_config('request.jwt.claim.sub',ua::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',ua,'role','authenticated')::text,true);execute 'set local role authenticated';
  body:=public.diriqent_reserve(c,op,'chat',null,'Test question',fp,500,null);
  assert public.diriqent_reserve(c,op,'chat',null,'Test question',fp,500,null)->>'id'=op::text,'reservation idempotence';passed:=passed+1;
  assert (public.diriqent_read(c)->>'availableUnits')::integer=9500,'exact reservation balance';passed:=passed+1;
  failure:=null;begin perform public.diriqent_reserve(c,op,'chat',null,'Changed',repeat('b',64),500,null);exception when others then failure:=sqlerrm;end;
  assert failure is not null,'fingerprint change denied';passed:=passed+1;
  failure:=null;begin perform public.diriqent_provider_claim(op,c,pa);exception when others then failure:=sqlstate;end;
  assert failure='42501','provider claim is service only';passed:=passed+1;
  failure:=null;begin update public.diriqent_operations set result=answer where id=op;exception when others then failure:=sqlstate;end;
  assert failure='42501','direct operation writes denied';passed:=passed+1;
  execute 'reset role';perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';
  body:=public.diriqent_provider_claim(op,c,pa,'{"scope":"FORGED","customers":[{"name":"FORBIDDEN"}]}');attempt:=(body->>'attemptId')::uuid;
  assert (body->>'claimed')::boolean and body->'context'->>'scope'<>'FORGED' and not (body->'context')::text like '%FORBIDDEN%','claim rebuilds trusted company context';passed:=passed+1;
  assert jsonb_array_length(body->'context'->'customers')=1,'allowed company customer only';passed:=passed+1;
  assert not (public.diriqent_provider_claim(op,c,pa)->>'claimed')::boolean,'provider can be claimed once';passed:=passed+1;
  body:=public.diriqent_settle(op,attempt,answer,true,1000,100,0,null);
  assert (body->>'charged_units')::integer=24,'actual usage costs 24 credit cents';passed:=passed+1;
  assert public.diriqent_settle(op,attempt,answer,true,1000,100,0,null)->>'charged_units'='24','settlement retry idempotent';passed:=passed+1;
  execute 'reset role';
  assert (select sum(reserved_delta)=0 and sum(credit_delta)=-24 from private.ai_credit_ledger where operation_id=op),'ledger balances after settlement';passed:=passed+1;
  failure:=null;begin update private.ai_credit_ledger set credit_delta=0 where operation_id=op;exception when others then failure:=sqlerrm;end;
  assert failure is not null,'ledger immutable';passed:=passed+1;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',ua,'role','authenticated')::text,true);execute 'set local role authenticated';
  perform public.diriqent_reserve(c,op_cancel,'chat',null,'Cancel before provider',fp,500,null);
  assert public.diriqent_cancel_unstarted(c,op_cancel)->>'state'='failed','unclaimed reservation cancelled';passed:=passed+1;
  assert public.diriqent_cancel_unstarted(c,op_cancel)->>'state'='failed','cancel retry idempotent';passed:=passed+1;
  perform public.diriqent_reserve(c,op_failed,'chat',null,'Provider unusable response',fp,500,null);
  execute 'reset role';perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';
  attempt:=(public.diriqent_provider_claim(op_failed,c,pa)->>'attemptId')::uuid;
  execute 'reset role';perform set_config('request.jwt.claims',jsonb_build_object('sub',ua,'role','authenticated')::text,true);execute 'set local role authenticated';
  failure:=null;begin perform public.diriqent_cancel_unstarted(c,op_failed);exception when others then failure:=sqlerrm;end;
  assert failure is not null,'claimed provider work cannot be cancelled as unstarted';passed:=passed+1;
  execute 'reset role';perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';
  body:=public.diriqent_settle(op_failed,attempt,null,false,1000,100,0,'unusable_result');
  assert body->>'charged_units'='0','unusable result charges zero customer credit';passed:=passed+1;
  execute 'reset role';
  assert (select provider_cost_microusd=3200 and unbilled_credit_units=24 from private.ai_provider_attempts where operation_id=op_failed),'provider cost separately preserved';passed:=passed+1;
  assert (select sum(reserved_delta)=0 from private.ai_credit_ledger where operation_id=op_cancel),'cancel releases exact reservation';passed:=passed+1;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',ua,'role','authenticated')::text,true);execute 'set local role authenticated';
  perform public.diriqent_reserve(c,op_demotion,'chat',null,'Reserved as manager',fp,500,null);
  execute 'reset role';update public.company_members set role='worker' where company_id=c and profile_id=pa;
  perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';
  failure:=null;begin perform public.diriqent_provider_claim(op_demotion,c,pa,'{"scope":"manager stale data"}');exception when others then failure:=sqlstate;end;
  assert failure='42501','demotion between reserve and claim denied';passed:=passed+1;
  execute 'reset role';perform set_config('request.jwt.claims',jsonb_build_object('sub',ua,'role','authenticated')::text,true);execute 'set local role authenticated';
  assert (select count(*)=0 from public.diriqent_operations where id=op),'manager history hidden after demotion';passed:=passed+1;
  body:=public.diriqent_cancel_unstarted(c,op_demotion);assert not body ? 'prompt','demoted owner releases reservation without sensitive history';passed:=passed+1;
  execute 'reset role';update public.company_members set role='company_admin' where company_id=c and profile_id=pa;
  perform set_config('request.jwt.claim.sub',uw::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',uw,'role','authenticated')::text,true);execute 'set local role authenticated';
  assert (select count(*)=0 from public.diriqent_operations where profile_id=pa),'same-company conversations remain private';passed:=passed+1;
  perform public.diriqent_reserve(c,op_worker,'chat',null,'Worker scope',fp,500,null);
  execute 'reset role';perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';
  body:=public.diriqent_provider_claim(op_worker,c,pw);attempt:=(body->>'attemptId')::uuid;
  assert jsonb_array_length(body->'context'->'customers')=0 and jsonb_array_length(body->'context'->'jobs')=0,'worker has no company directory or unassigned jobs';passed:=passed+1;
  perform public.diriqent_settle(op_worker,attempt,answer,true,100,10,0,null);
  execute 'reset role';perform set_config('request.jwt.claim.sub',uf::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',uf,'role','authenticated')::text,true);execute 'set local role authenticated';
  assert (select count(*)=0 from public.diriqent_operations where company_id=c),'cross-company RLS';passed:=passed+1;
  failure:=null;begin perform public.diriqent_operation(c,op);exception when others then failure:=sqlstate;end;assert failure='42501','cross-company RPC denied';passed:=passed+1;
  execute 'reset role';perform set_config('request.jwt.claim.sub',ua::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',ua,'role','authenticated')::text,true);execute 'set local role authenticated';
  perform public.diriqent_reserve(c,op_proposal,'proposal',null,'Prepare draft',fp,500,null);
  execute 'reset role';perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';
  attempt:=(public.diriqent_provider_claim(op_proposal,c,pa)->>'attemptId')::uuid;perform public.diriqent_settle(op_proposal,attempt,answer,true,100,10,0,null);
  execute 'reset role';perform set_config('request.jwt.claims',jsonb_build_object('sub',ua,'role','authenticated')::text,true);execute 'set local role authenticated';
  payload:=jsonb_build_object('title','Confirmed synthetic job','description','Reviewed exact scope','address','Test','customerId',foreign_customer,'startAt','2026-11-01T08:00:00Z','endAt','2026-11-01T09:00:00Z','price',1000);
  failure:=null;begin perform public.diriqent_prepare_job(c,op_proposal,payload);exception when others then failure:=sqlerrm;end;assert failure is not null,'foreign customer denied';passed:=passed+1;
  proposal:=public.diriqent_prepare_job(c,op_proposal,payload||jsonb_build_object('customerId',customer));
  assert proposal->'payload'->>'customerName'='Allowed customer','confirmation displays canonical customer';passed:=passed+1;
  failure:=null;begin perform public.diriqent_confirm_job(c,op_proposal,repeat('0',64));exception when others then failure:=sqlerrm;end;assert failure is not null,'stale confirmation hash denied';passed:=passed+1;
  job:=public.diriqent_confirm_job(c,op_proposal,proposal->>'payload_hash');
  assert public.diriqent_confirm_job(c,op_proposal,proposal->>'payload_hash')=job,'explicit confirmation creates one job';passed:=passed+1;
  body:=public.diriqent_export(c,'chat',op);assert jsonb_array_length(body->'operations')=1 and jsonb_array_length(body->'proposals')=0,'single export excludes unrelated proposals';passed:=passed+1;
  execute 'reset role';update public.company_members set role='manager' where company_id=c and profile_id=pa;execute 'set local role authenticated';
  failure:=null;begin perform public.diriqent_prepare_job(c,op_proposal,payload||jsonb_build_object('customerId',customer));exception when others then failure:=sqlstate;end;assert failure='42501','manager cannot create Core jobs';passed:=passed+1;
  execute 'reset role';update public.company_members set role='company_admin' where company_id=c and profile_id=pa;
  update private.company_test_module_grants set revoked_at=now(),revocation_reason='Synthetic history-only replacement' where company_id=c and product='ai_assistant';
  insert into private.company_test_module_grants(company_id,product,source_ref,reason,valid_from,valid_until,history_until,capabilities) values(c,'ai_assistant',marker||'-history','Synthetic read-only history',now()-interval '1 day',now()+interval '1 day',now()+interval '1 day',array['ai_assistant.history.read']);
  execute 'set local role authenticated';
  assert not (public.diriqent_read(c)->>'canRun')::boolean,'history-only entitlement prevents new chat';passed:=passed+1;
  failure:=null;begin perform public.diriqent_export(c,'chat',op);exception when others then failure:=sqlstate;end;assert failure='42501','read entitlement alone cannot export';passed:=passed+1;
  perform public.diriqent_reserve(c,op_ocr,'smart_quotes.ocr',null,'Read domain document',fp,500,'synthetic.png');
  assert public.diriqent_cancel_unstarted(c,op_ocr)->>'state'='failed','domain OCR works without chat entitlement';passed:=passed+1;
  execute 'reset role';
  insert into private.company_test_module_grants(company_id,product,source_ref,reason,valid_from,valid_until,history_until,capabilities) values(c,'ai_assistant',marker||'-export','Synthetic history export permission',now()-interval '1 day',now()+interval '1 day',now()+interval '1 day',array['ai_assistant.history.read','ai_assistant.history.export']);
  update private.company_test_module_grants set revoked_at=now(),revocation_reason='Synthetic Core disabled' where company_id=c and product='diriqo_core';
  execute 'set local role authenticated';
  assert (public.diriqent_export(c,'chat',op)->>'complete')::boolean,'history export remains available with Core disabled';passed:=passed+1;
  execute 'reset role';
  raise exception 'rollback AI synthetic fixtures' using errcode='PT001';
 exception when sqlstate 'PT001' then null;
 end;
 assert not exists(select 1 from public.companies where id in(c,foreign_c)),'all fixtures rolled back';
 perform set_config('diriqo.ai_test_result',jsonb_build_object('passed',passed,'fixtures','rolled_back','concurrency','not tested in single session','provider','no external calls')::text,true);
end $test$;
select current_setting('diriqo.ai_test_result')::jsonb as result;
